window.VD=window.VD||{};window.VD["vw/transporter-t6-1"]={"transporter-t6-1-120-km-h-overtaking-alert":"<p><strong>Purpose: </strong>To activate or deactivate a message reminding you that you are exceeding the 120km/h speed limit.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.  </p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:  </strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.  </p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Wizard</strong>”.  </p>\n<p><strong>5</strong> – Select byte<strong>“0”</strong> <br/>Then check to enable or uncheck to disable the box in<strong>“6”</strong>:<strong>“Speed warning at 120 kph (75 mph) active</strong>”.  </p>","transporter-t6-1-activate-daytime-running-lights-drl-only-in-auto-position":"<p><strong>Purpose:</strong> Enables daytime running lights (DRL) only when the headlight control switch is in the “auto” position.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Daytime running lights—Daytime running lights only in the AUTO position</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_drl_auto_switch-c7669352.webp\"/></figure>","transporter-t6-1-activate-driving-school-mode":"<p><strong>Purpose:</strong> Adds a driving-school mode view to Discover, displaying turn signals, speed, etc. (also ideal for accompanied driving).  <br/><br/><br/><strong>Warning! There are 3 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule function list CAN-Driving_school</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school_over_threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6384-e21a59b4.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/discoverautoecole-1024x768-75d0428f.webp\"/></figure>","transporter-t6-1-activate-hidden-menu":"<p><strong>Purpose:</strong> Activates the green hidden menu (green menu, hidden menu, testmode, engineer mode) on Discover MIB2.  </p>\n<p>/! Caution: Making certain changes in the hidden menu may cause MIB2 to lock up or not start at all /!<br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“S12345</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Developer mode</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the value<strong>“activated</strong>”.</p>\n<p><em>Restart MIB2, keep MENU button pressed until testmode menu appears</em><br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/developermode-bfa51f40.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/developermode2-1024x576-7a0c833c.webp\"/></figure>","transporter-t6-1-activate-lane-assist-memory-function":"<p><strong>Purpose:</strong> to store the Lane Assist function in memory. If you deactivate it, the Lane Assist will not automatically resume the next time you start up.  <br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1 (For Camera A5 5Q0 / 3Q0) :</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong>Personalization of lane dept. warning Cl. 15 on  </strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“last setting </strong>” and confirm.</p>\n<hr/>\n<p><strong>Line 1 (For Camera A5 2Q0):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>”<br/>Then check Bit<strong> 0-1</strong><strong>“03 Configuration_for_lane_departure_warning_Kl15, Last_setting</strong>”.</p>","transporter-t6-1-activate-off-road-mode-on-discover":"<p><strong>Purpose:</strong> to add Offroad mode to Discover Pro or Discover Media with navigation.  <br/><br/><br/><strong>Warning! There are 3 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-compass_0x15</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Compass</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Compass_over-threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/offroad-700x500-1-830de5b6.webp\"/></figure>","transporter-t6-1-activate-rearview-camera-retrofit":"<p><strong>Purpose:</strong> to activate the reversing camera after it has been retrofitted to the Discover.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>6</strong> – Select byte <strong>19</strong><br/>. Then set bit <strong>4</strong> to “Rear View Camera (RVC) Low installed (PR-KA1).”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/C25A41FA-66F7-4FC9-B7F4-1761395A1D01-1024x483-11bbd3cf.webp\"/></figure>\n<p><strong>Line 2 (Optional, if parking assist is available)</strong> <strong>:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte <strong>02</strong><br/>. Then, for bits <strong>4-5</strong>, select<em> “10 Camera Type: Rear View Camera (RVC) installed.”</em></p>\n<p><strong>Hardware upgrade :</strong></p>\n<p>The camera’s video cable is connected to the infotainment control unit. It is installed in the glovebox.   <br/><br/>The 2 pins of the reversing camera are used in the 12-pin quadlock (blue). Usable cable set: Part no. 000 979 009 E <br/><br/>Quadblock Assignment :<br/><br/>Pin 6 = video line<br/>Pin 12 = shielding</p>","transporter-t6-1-activate-trailer-coupling-retrofit":"<p><strong>Purpose:</strong> Enables the installation of a retrofit trailer hitch (trailer/towbar retrofit).  </p>\n<p><em>Caution! The configuration in the control unit for motor 01 is not supported for certain models. In this case, the coding can be skipped. Control units that are not installed can also be skipped. Please note that certain coding steps must be performed based on the part numbers of the installed components (camera).      </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Capture-decran-2024-01-09-215831-4f89678c.webp\"/></figure>\n<p><strong>Warning!! Depending on the modules you have installed, there are up to 12 coding lines to complete here; most ECUs require a long coding process with a “trailer” that must be enabled!  </strong><br/><br/><strong>Proceed :</strong><br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Select <strong>“Installation List”</strong><br/><br/><strong>5</strong> – Check the box next to “<strong>69 – Trailer</strong>” in the list</p>\n<p><strong>6</strong> – Save coding</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailergateway-3cb3c873.webp\"/></figure>\n<p><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“01 – Motor</strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>05</strong>“<br/>. Then check bit “<strong>4</strong>“: “<strong>Trailer installed</strong>“</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailermoteur-fdaad0ca.webp\"/></figure>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong><strong>“09 – Cent. Elect.”</strong></strong>“.</p>\n<p><em>For power plants <strong>with</strong> coding:</em><br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>,” then click on “<strong>Long Coding Helper</strong>“<br/><br/><strong>5</strong> – Select byte “<strong>01</strong>“<br/>Then, in the “<strong>Bit 0-7</strong>” drop-down menu, select “<strong>01 Trailer Connector Diagnosis active</strong>“.</p>\n<p><strong><em>Or</em></strong> Byte<strong>“01</strong>” check <strong>Bit 1</strong><strong>“Trailer Hitch Control Module Installed</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailercentrelec-0a9e9b3c.webp\"/></figure>\n<p><em>For power plants <strong>without </strong>coding :</em></p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Networking trailer connection device</strong>”.<br/><br/><strong>7</strong> – On this same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“built in”</strong> and confirm.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“03 – ABS brake</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“24990</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“trailer stabilization</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select “<strong>Active</strong>” and then confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter code<strong>“71679</strong>” (optional code)<br/><br/><strong>5</strong> – Click ” <strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>“<br/><br/><strong>6</strong> – Select byte<strong>“03</strong>”<br/>Then check Bit<strong> 0-1</strong> “01 Trailer Hitch installed (manually removable)”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailerpark-212dd6b1.webp\"/></figure>\n<p><br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>13 – Auto Dist. Reg. </strong>“.<br/><br/><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>14117</strong>” or “<strong>20103</strong>“<br/><br/><strong>5</strong> – Click ” <strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>“<br/><br/><strong>6</strong> – Select byte<strong>“02</strong>” (camera 5Q0) or<strong>“03</strong>” (camera 2Q0/3Q0)<br/>Then check Bit<strong> 3</strong> “Trailer Recognition Control Module installed”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailerdist-da789d91.webp\"/></figure>\n<p><br/><br/><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>34 – Correct. Assiet. </strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select the “<strong>00</strong>” byte<br/>Then set bit <strong>7</strong> (“trailer, 0 = not installed / 1 = installed”)<br/><br/><br/><strong>Line 8:</strong></p>\n<p><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>3C – Lane Change</strong>.”<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte<strong>“02</strong>” (camera 5Q0) or<strong>“00</strong>” (camera 2Q0/3Q0)<br/>Then check Bit <strong>4-7</strong> “10 or 20 ECU for draw bar, with ECU for draw bar”.<br/><br/><br/><br/><strong>Line 9:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>6C – Rearview Camera</strong>.”<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>04</strong>“<br/>Then set bit <strong>0</strong> (“equipment_ahk, installed”)<br/><br/><br/><strong>Line 10:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>6D – Trunk Electrical System </strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>01</strong>“<br/>Then set bit <strong>7</strong> (“trailer, 0 = not installed / 1 = installed”)<br/><br/><strong>Line 11:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Front, Sensors, Driver Assistance   </strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.</p>\n<p><strong>5</strong> – Click ” <strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>“</p>\n<p><strong>6</strong> – <em>Choose the line according to your camera reference!</em></p>\n<p>Select byte<strong>“16</strong>” (Camera 5Q0)</p>\n<p>Then check bit <strong>0-7</strong> “01 trailer_control_module, installed”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailera5-685c17e4.webp\"/></figure>\n<p><em><strong>OR</strong></em></p>\n<p>Select byte<strong>“11</strong>” (Camera 3Q0)</p>\n<p>Then set bit<strong> 0 ( </strong>“AAG, 0 = not_coded / 1 = coded”)</p>\n<p><em><strong>OR</strong></em></p>\n<p>Select byte<strong>“05</strong>” (Camera 2Q0)</p>\n<p>Then set bit <strong>4</strong> (“AAG, 0 = not_coded / 1 = coded”)</p>\n<p><strong>Line 12:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong><strong>69 – Trailer</strong></strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte<strong>“01</strong>”<br/>Then check Bit <strong>0-3</strong> “01 Diagnosis of the line to the socket, active”.</p>\n<p>Select byte<strong>“03</strong>”<br/>Then check Bit<strong> 0-3</strong> “01 Terminal 30 output (pin 9 socket), activated”.</p>\n<p><em><strong>OR</strong></em></p>\n<p>Select byte<strong>“04</strong>”<br/>Then check Bit<strong> 0-7</strong> “02 Terminal 30 output switched (pin 10) Trailer connected”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailer69-acbfa990.webp\"/></figure>","transporter-t6-1-corner-lights-activation":"<p><br/><strong>Purpose:</strong> Allows you to turn on the corner lights along with the fog lights.  <br/><br/><br/><strong>Warning! There are 6 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte12NL LB45-Lichtfunktion C 12</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Abbiegelicht links</strong>” and then confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte12NL LB45-Dimmwert CD 12</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>of the page.<br/>From this menu, select “<strong>100</strong>” for halogen lights or “<strong>127</strong>” for LEDs, then confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte12NL LB45-Dimming Direction CD 12</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu further down<br/>.<br/>From this menu, select “<strong>maximize</strong>” and then confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte13NL RB5-Lichtfunktion C 13</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Abbiegelicht rechts</strong>” and then confirm.<br/><br/><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte13NL RB5-Dimmwert CD 13</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>of the page.<br/>From this menu, select “<strong>100</strong>” for halogen lights or “<strong>127</strong>” for LEDs, then confirm.<br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Leuchte13NL RB5-Dimming Direction CD 13</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu further down<br/>.<br/>From this menu, select “<strong>maximize</strong>” and then confirm.</p>","transporter-t6-1-activation-of-progressive-interior-lighting":"<p><strong>Purpose:</strong> turns interior lights (door knobs, dashboard, center console) on and off gradually. By default, interior lights are switched on and off immediately with the headlights. Activating this function will cause a slow fade effect each time the interior lights are switched on or off. (Interior Light Fade in/out)     <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Interior lighting-KL58 Einschalten mit Rampe</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/kl58rampe-e361a4ce.webp\"/></figure>\n<p>OBDeleven:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/KL58rampeOBDeleven-1fdea7c1.webp\"/></figure>","transporter-t6-1-automatic-door-unlocking-with-dsg-in-p-position":"<p><strong>Purpose:</strong> Automatically unlocks all doors when the DSG automatic transmission is shifted to the “P” position.  </p>\n<p><strong>Procedure: </strong><br/><strong>1 –</strong> Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2 –</strong> Switch on the ignition and run the VCDS program.</p>\n<p><strong>3 –</strong> Click on <strong>“Select”</strong>, then click on <strong>“09 – Cent. Elect.”</strong>.</p>\n<p><strong>4 –</strong> Click <strong>“Security Access – 16,”</strong> then enter the code <strong>“31347”</strong></p>\n<p><strong>5 –</strong> Click on <strong>“Adaptation – 10”</strong>.</p>\n<p><strong>6 –</strong> At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select <strong>“Access control – Autounlock NAR”</strong></p>\n<p><strong>7 –</strong> On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select <strong>“active</strong>, <strong>“</strong> then confirm.</p>","transporter-t6-1-brake-disc-drying":"<p><strong>Purpose:</strong> to adjust the intensity of brake disc drying. If your car has a tendency to squeal when parked in wet weather, for example, the annoying drying of the disc brakes can be reduced or even completely deactivated, so that there are no scratches or squeaks.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“03- Electronic brakes</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“40304</strong>“.</p>\n<p><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>“.<br/><br/> 6 – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“brake disc drying</strong>“<br/><br/> 7 – On this same page, there is a second drop-down menu but towards the bottom<br/>of the page.<br/>On this, choose the value accordingly to your choice: ” <strong>not activated, low, medium, high</strong> ” then validate.</p>","transporter-t6-1-comfort-turn-signal":"<p><strong>Purpose:</strong> to set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Turn signal control-Komfortblinken Blinkzyklen</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose between<strong>“3</strong>” and<strong>“5</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_clignotant_confo-f1a2f919.webp\"/></figure>\n<p><em>Information: If, after coding, the number of flashes has not changed, on your MIB screen: CAR -&gt; Settings -&gt; Factory settings -&gt; Lighting (Your interior lighting configurations will also be reset).</em></p>","transporter-t6-1-coming-home-automatic":"<p><strong>Purpose:</strong> Automatically activates the Coming Home function (no need to make a headlight call).  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Comfort Illumination—Coming Home Status</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“automatic</strong>” and confirm.</p>","transporter-t6-1-daytime-running-light-deactivation-drl-with-handbrake-on":"<p><strong>Purpose:</strong> to deactivate the daytime running lights (DRL) using the handbrake.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Daytime running lights-Tagfahrlicht Dauerfahrlicht bei Handbremse abschalten</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-5G---Desactiver-les-feux-de-jours-DRL-avec--6d661897.webp\"/></figure>","transporter-t6-1-daytime-running-lights-drl-on-off-with-discover":"<p><strong>Purpose:</strong> Allows you to turn the daytime running lights (DRL) on or off from the Discover in the CAR menu.  </p>\n<p>ATTENTION to your country’s regulations and technical inspection for daytime running lights!<br/>However, if you’re coding in your car to avoid using too much of your battery, this is a good solution…  </p>\n<p><br/><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition switched off, connect your official VAG-COM VCDS cable to the computer, then connect the other end to your vehicle’s diagnostic port or your OBDeleven unit.<br/><br/><strong></strong> 2 – Turn on the ignition, then launch the VCDS program or the OBDeleven app.</p>\n<p><strong>VCDS:</strong><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Daytime running lights—Tagfahrlicht—Activation possible via BAP or control sequence</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_feux_jour_drl-0a93900d.webp\"/></figure>\n<hr/>\n<p><strong>OBDeleven:</strong></p>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdeleven09-d37c6d29.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenadapt-0d774aea.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenaussenlicht-0747a95f.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdeleventagfahrlicht-78f4d30c.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdeleventagfahrlichtactive-e1f21fc0.webp\"/></figure>\n</figure>\n<hr/>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/activedrlvagcoding-c1ee180c.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/activedrlvagcoding2-bf0103c8.webp\"/></figure>\n</figure>","transporter-t6-1-deactivate-mirrorlink":"<p><strong>Purpose:</strong> Allows you to disable or remove MirrorLink from App-Connect on the MIB Discover. The MirrorLink service has not been natively available on Android since June 1, 2020. For a direct connection to Android Auto.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicle configuration-Mirror_link</strong>“.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Disabled</strong>” and confirm.</p>","transporter-t6-1-deactivate-open-door-alarm-using-contact":"<p><strong>Purpose:</strong> to deactivate the alarm which is triggered when the door is opened and the contact is in position P.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Ignition active message</strong>” / ”  <strong>Message ignition active. trigger </strong>  “<br/><br/><strong>6</strong> – On this same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“tbd</strong>” /<strong>“No display</strong>” / “<strong>Aucun affichage</strong>” then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_ignition_active_-e1e03128.webp\"/></figure>","transporter-t6-1-deactivate-switch-on-low-beam-message":"<p><strong>Purpose:</strong> Disables the warning message or dialog prompting the driver to turn on the low beams when the headlight switch is in position 0.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/allumerfeuxdecroisement1-1024x609-756a4f05.webp\"/></figure>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Außenlicht_uebergreifend-Fahrlichtwarnung_Hinweis_Konfig</strong>” / ” <strong>driving light_hint_config</strong> ”  <br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom of the page.<br/>From this menu, select “<strong>kein_Hinweis</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/allumerfeuxdecroisement2-f3950d1b.webp\"/></figure>","transporter-t6-1-deactivation-of-parking-aid-activation-beep":"<p><strong>Purpose:</strong> to deactivate the beep when reverse gear is engaged or when parking assistance is activated manually.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>10 – Parking Assistance</strong>.”</p>\n<p><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“</p>\n<p><strong>5</strong> – Click on ” <strong>Adaptation – 10</strong> “.</p>\n<p><strong>6</strong> – Select ” <strong>Tonalité d’activation de l’aide au stationnement </strong>” / ” <strong>Park assist activation</strong> <strong>tone </strong>” / ” <strong>Aktivierungston für Einparkhilfe </strong>” from value list</p>\n<p><strong>7</strong> – Select ” <strong>Off”</strong> in the second value list  <br/></p>","transporter-t6-1-delete-belt-alarm":"<p><strong>Purpose:</strong> Turns off the audible alarm and the indicator light on the dashboard when driving without a seatbelt.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>“.</p>\n<p><strong>5</strong> – Select byte <strong>0</strong>:<br/>Bits <strong>2–4</strong>: Select <strong>“Seat Belt Warning inactive”</strong> from the drop-down list.</p>\n<p><strong><em>OR</em></strong></p>\n<p><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>20103</strong>“<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select <strong>“</strong> <strong>Deactivate</strong> <strong></strong> <strong>Seat Belt Warning.”</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select “<strong>Oui</strong>” / “<strong>Yes</strong>” and then confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8U0_920_940_Module17_Adaptation_desactivate_seat_b-77d3b532.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","transporter-t6-1-disable-am-frequency-on-discover":"<p><strong>Purpose:</strong> to disable the AM radio frequency on Discover (AM radio frequency is rarely used, unlike FM radio frequency).  </p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select Byte <strong>14</strong></p>\n<p>Set bit <strong>1</strong> <strong>“AM_disable </strong> </p>\n<figure>\n</figure>","transporter-t6-1-disable-rear-wiper-when-reversing":"<p><strong>Purpose:</strong> deactivates or reverses the rear wiper when reverse gear is engaged.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Rear Window Wiper-Traenenwischen Heck</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom of the page.<br/>Select<strong>“active</strong>” to activate or<strong>“not active</strong>” to deactivate, then confirm.</p>","transporter-t6-1-disable-right-hand-overtaking-prevention":"<p><strong>Purpose:</strong> to deactivate the ACC lane assist system, e.g. when on the freeway and there is a traffic jam in the left lane, the vehicle starts to slow down.  </p>\n<p><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>13 –  <strong>Auto Dist. Reg</strong></strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select byte<strong>“02</strong>”<br/>Then uncheck Bit<strong>“5</strong>”: “<strong><strong>overtaking_right_prevention</strong></strong>”</p>\n<p>OBDeleven: Select <strong>“overtaking_right_prevention”</strong><br/>Change from “activated” to “Deactivated”.</p>","transporter-t6-1-door-lock-unlock-confirmation-beep-horn":"<p><strong>Purpose:</strong> to set confirmation of door locking/unlocking with beep (alarm) or horn.  <br/><br/><br/><strong>Warning!! There are 5 lines of code to write here—actually, 6. </strong> <em>(After programming, if it doesn’t work, enable the option on your screen in CAR – Open/Close Settings – check “Audible Confirmation”)</em> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Unlock acoustic feedback</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Yes</strong>” and then confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Acknowledgement signals—Lock Akustische Rückmeldung</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Yes</strong>” and then confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals-Akustische Rueckmeldung global</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Menuesteuerung Akustische Rückmeldung</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Duration of the acoustic feedback from the single horn</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this, choose<strong>“normal</strong>” or<strong>“kurz</strong>” (for a short signal), then confirm.<br/><br/><strong><br/>!!! If your vehicle is not equipped with an alarm, here is the code you need to change to activate the horn </strong>  :<br/><br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Akustische Rückmeldung Signalhorn</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7559-1024x495-1f01c127.webp\"/></figure>","transporter-t6-1-fan-speed-display-for-air-conditioning-in-auto-mode":"<p><strong>Purpose:</strong> to display fan speed when automatic air-conditioning mode is activated. (Climatronic fan speed display Auto mode)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“08 – Climatronic</strong>” (or<strong>“08 – Auto HVAC</strong>”, depending on your VCDS version).<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“11</strong>”<br/>Then check Bit<strong>“6</strong>”:<strong>“Blower Status Display in Auto-Mode active</strong>”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5G0-907-044-R_Module08_Byte11_v2-939963df.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/affichageclimautomqb-f32e9600.webp\"/></figure>","transporter-t6-1-fold-down-mirrors-with-ignition-on":"<p><strong>Purpose:</strong> Enables automatic folding of mirrors when the ignition is switched on, rather than when the vehicle is locked.  <br/><br/><br/><em>The vehicle must be equipped with the “Electrically folding mirrors (with comodo in door)” option, and the coded option in the tuto must automatically fold the mirrors.  </em><br/><em>Caution: Does not work properly with vehicle equipped with KESSY option</em>.  <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Mirror adjustment /</strong><strong>spiegelverstellung-Signalisierung_Spiegelanklappung</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“inactive</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7297-1024x746-ed161cb7.webp\"/></figure>","transporter-t6-1-hill-start-assist":"<p><strong>Purpose:</strong> Allows you to adjust the operation of Hill Start Assist. (Hill Hold)   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“03 – ABS</strong><strong>Brakes </strong>”.<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Hill Start Assistant</strong>.”<br/><br/><strong>6 – </strong> On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select the value based on your preference:</p>\n<ul>\n<li>“<strong>normal</strong>” (default value)</li>\n<li>“<strong>Early</strong>” (faster triggering)</li>\n<li>“<strong>Late”</strong> triggering</li>\n</ul>\n<p>then click “Submit.”</p>","transporter-t6-1-increase-gas-pedal-sensitivity":"<p><strong>Purpose:</strong> to increase accelerator pedal sensitivity. (better acceleration response with DSG, more significant than with manual).  <br/><br/>Proceed : <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/></p>\n<p><strong>Line 1:</strong> <br/><br/> 3 – Click on<strong>“Select”</strong>, then click on<strong>“44 – Steering Assistance</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“19249</strong>“.  </p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Commutation profil de conduite</strong>” /<strong>“Driving profile switchover</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this, choose the value: “<strong><em>directly: controlled by threshold value</em></strong>” / “<em><strong>Direct controlled over threshold value</strong></em>” then confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7198-330b03e4.webp\"/></figure>","transporter-t6-1-kessy-automatic-keyless-entry":"<p><strong>Purpose:</strong> Automatically locks the vehicle as soon as you leave it with the key, provided that the KESSY system (keyless entry, locking, and starting system) is installed. Unfortunately, the function that folds the exterior mirrors is not controlled and may need to be performed manually using the key if necessary.   </p>\n<p><br/><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>05 – Access Authorization/Startup</strong>.”</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click “<strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>.”<br/><br/><strong>6</strong> – Select byte “<strong>2</strong>“<br/>. Then set bit “<strong>5</strong>” (module 5Q0) <em><strong>OR</strong></em> Bit “<strong>4</strong>” (Module 3Q0) <em>“Locking for Door Slamming active”</em></p>\n<p><strong>Line 2: </strong></p>\n<p><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong><strong>05 – Access Authorization/Startup</strong></strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>“.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>internal_passive_entry_exit_byte1-passive_exit_door_slam_lock</strong>“<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.</p>","transporter-t6-1-key-operation-even-with-ignition-on":"<p><strong>Purpose:</strong> Allows you to use the key and lock the vehicle with the ignition switched on or the engine running. (Very practical with a Keyless Kessy key)  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access control-Funk bei Klemme 15 ein</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>","transporter-t6-1-lane-assist-settings":"<p><strong>Purpose</strong>: Adjusts lane departure warning, driver inactivity deactivation threshold, steering assist intensity and steering wheel vibration intensity.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<h4><strong>Adjusting the driver inactivity deactivation threshold</strong>:</h4>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>A5 – Front Camera</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20103</strong>”</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em><em>“Deactivation threshold for lane departure warning Driver inactivity</em>” or <em>“Deaktivierungsschwelle Fahrerinaktivität”.</em><br/></p>\n<p>Adjust value accordingly<br/>Setting range:<br/><br/>– early (deactivates Lane Assist within 7 seconds)<br/>– medium (factory setting, deactivates Lane Assist within 7 to 10 seconds)<br/>– late (deactivates Lane Assist within 11 to 15 seconds)</p>\n<h4><strong>Adjust the intensity of the steering assist</strong>:</h4>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>A5 – Front Camera</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20103</strong>”</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em> <em>“Lane Departure Warning Intensity Steering Assistance”</em> or <em>“Intensität Lenkradunterstützung”.</em><br/></p>\n<p>Adjust value accordingly<br/>Setting range:<br/><br/>– low (Lane Assist switches off earlier depending on ambient conditions, as less/more sensitive steering interventions are carried out)<br/>– medium (factory setting)<br/>– high (Lane Assist switches off later depending on ambient conditions, as more/more intensive steering interventions are carried out)</p>\n<h4><strong>Adjust steering wheel vibration intensity</strong>:</h4>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>A5 – Front Camera</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20103</strong>”</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em><em>“Steering wheel vibration intensity</em>” or <em>“Intensität Lenkradvibration”.</em><br/></p>\n<p>Adjust value accordingly<br/>Setting value range:<br/><br/>– low<br/>– medium (factory setting)<br/>– high</p>","transporter-t6-1-lap-timer":"<p><strong>Purpose:</strong> to add the stopwatch to the ODB/Virtual Cockpit.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“3</strong>”:<strong>“Lap Timer active</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/GOLF-7-VAGCOM---CHECK-DES-AIGUILLES-1-dab4b41b.webp\"/></figure>\n<p><strong>Alternative method if the 1st doesn’t work!! :</strong><br/><br/><br/><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Lap counter</strong>”.<br/><br/><strong>6</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Display</strong>” and confirm.</p>\n<figure>\n</figure>","transporter-t6-1-light-assist-always-active":"<p><br/><strong>Purpose:</strong> automatically activates the high beam assistant on start-up if it was active before the ignition was switched off.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Assistance light functions-Fernlichtassistent Reset</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“not active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/fernlicht-6b04f01d.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/lightassist-1a9a5499.webp\"/></figure>","transporter-t6-1-memory-for-heated-seats":"<p><strong>How it works :</strong> When you switch on the heated seat(s), as soon as you remove the key from the ignition the setting is immediately switched off. With this activation, when you switch the ignition back on, the seat will have returned to the level at which you left it.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“08 – Climatronic</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose  </p>\n<p>“<strong>Retention of driver’s seat heater level</strong>” for <strong>Driver’s seat heater memory</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3AA-907-044-AG_Module08_Adaptation_retention_of_dr-51646659.webp\"/></figure>\n<p>and/or<strong>“Retention of passenger’s seat heater level</strong>” for <strong>Passenger seat heater memory</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3AA-907-044-AG_Module08_Adaptation_retention_of_pa-61b11e06.webp\"/></figure>\n<p><br/><br/><strong>6</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>","transporter-t6-1-mirror-folding-adjustment-by-remote-control":"<p><strong>Purpose:</strong> Allows you to set the option to fold the side mirrors using the remote control when locking the vehicle. <br/><br/><br/><em>The vehicle must be equipped with the “Power-folding side mirrors” option</em> <em>!</em> <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<em><br/></em><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access Control 2-Funk Spiegelanklappung Modus</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select the value that suits your needs, then confirm.</p>\n<ul>\n<li>Default: <strong>“by convenience operation via remote control key”</strong> = press and hold the button on the key fob to fold the outside mirrors.</li>\n<li>Alternative: <strong>“by look command via remote control key”</strong> “by looking command via the remote control key” = briefly press the button on the key fob to fold the side mirrors.</li>\n</ul>","transporter-t6-1-modify-warning-thresholds-for-icy-conditions":"<p><strong>Purpose:</strong> Allows you to select the outside temperature value for the risk of icy conditions for which the warning is displayed on the dashboard (Ice Warning).  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Outsitde temperature p ice warning entry temperature</strong>” for the value at which the alert sounds to warn of frost. (Origin: 4°C)<br/>Then choose<strong>“Outsitde temperature p ice warning <strong><strong>exit</strong></strong> temperature</strong>” for the value at which the frost alert ends. (Origin: 6°C)  </p>\n<p><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose the temperature value you want.</p>","transporter-t6-1-needle-check":"<p><strong>Purpose:</strong> to activate the scanning of the speedometer needles when the car is started. (Works with Virtual Cockpit) (Needle Sweep)  <br/><br/><br/><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“0</strong>”:<strong>“Gauge Test/Needle Sweep (Stading) active</strong>”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/GOLF-7-VAGCOM---CHECK-DES-AIGUILLES-1-dab4b41b.webp\"/></figure>","transporter-t6-1-oil-temperature-on-odb":"<p><strong>Purpose:</strong> to display oil temperature on the ODB/Virtual Cockpit.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“10</strong>”<br/>Then check Bit<strong>“1</strong>”:<strong>“Display Oil Temperature</strong>”.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/temperature-huile-vagcoding-ef203ab4.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/temphuileg7-1024x768-7b5d2875.webp\"/></figure>","transporter-t6-1-rear-lights-activated-with-daytime-running-lights-drl":"<p><strong>Purpose:</strong> Enables the rear lights to turn on when the daytime running lights (Scandinavian DRL) are activated (This method turns on the instrument panel lights) <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Daytime running lights—Tagfahrlicht—Dauerfahrlicht activated in addition to parking lights</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu near the bottom of the page.<br/>From this menu, select “<strong>active</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_feux_arriere_drl-eff83f7a.webp\"/></figure>","transporter-t6-1-rear-window-defrost-time-setting":"<p><strong>Purpose:</strong> to set the duration of rear window defrost operation. (Multivan, California…)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Window heater-Heckscheibenheizung zeitwert</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose a value expressed in<strong>“s</strong>” (seconds) (default value:<strong>“600 s/10 min</strong>”) then validate.</p>","transporter-t6-1-make-up-quantity-displayed-on-odb":"<p><strong>Purpose:</strong> Displays the amount of fuel needed to completely fill your tank on the ODB / Virtual Cockpit. <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>“, then on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>10</strong>“<br/>. Then check bit “<strong>4</strong>“: “Volume to Be Replenished”</p>\n<p>If it’s a hidden bit, you need to replace the <strong>0</strong> with a <strong>1</strong> in “<strong>Binary</strong>.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-MKVII-Affichage-quantite-carburant-ODB-1024x3-6098b6ed.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/refuel-quantity-golf7-504de88f.webp\"/></figure>","transporter-t6-1-reprogramming-a-new-battery":"<p><strong>Purpose:</strong> Allows you to reprogram or recode all data for the new battery after it has been replaced. <br/><br/><br/><strong>Warning! There are 5 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click ” <strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Adaptation—Nominal Battery Capacity</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select the rated capacity listed on your battery. For example: “<strong>70Ah</strong>“<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Adaptation—Battery Technology</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu further down<br/>.<br/>From this menu, select the corresponding value<br/>. For example: For the VARTA E39, select “<strong>Etoffe</strong>” / “<strong>Fleece</strong>” for AGM.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Adaptation—Battery Manufacturer</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu further down the page<br/>.<br/>From this menu, select the corresponding brand:<br/>For example: For the VARTA E39, select “<strong>VAO</strong>.”<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Configuration—Battery Serial Number</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>In this menu, enter the corresponding serial number:<br/>Note: Enter only the <strong>last 10 digits</strong> of the serial number.<br/><br/><strong>Line 5 (AGM battery option):</strong></p>\n<p><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Cliquer sur “<strong>Codage – 07</strong>” puis cliquer “<strong>Assistant Codage Long</strong>“<br/><br/><strong>5</strong> – Select the octet “<strong>3</strong>,” then the byte “<strong>3</strong>“<br/><br/><strong>6</strong> – Finally, change the value of bits 4–7 to “<strong>30—Battery Architecture/Type: Absorbent Glass Matt (AGM)</strong>,” then confirm.</p>\n<hr/>\n<p><strong>Battery Status Detection Features:</strong></p>\n<p><br/>The battery status detection in the battery data module calculates the following values, which are transmitted via the LIN bus to the J533 diagnostic data bus interface:<br/>1 “battery not present” detection: if the battery data module does not detect a battery for<br/>more than 30 seconds, a corresponding bit is set to 1<br/>2 voltage that temporarily allows for optimal battery charging<br/>3 “engine start capability” bit. It indicates whether the battery is currently capable of starting<br/>the engine or not<br/>4. The amount of charge that can still be temporarily drawn from the battery before reaching the limit of<br/>its ability to start the engine<br/>5. The battery’s current state of charge<br/>6. Battery aging. Battery aging can be determined using parameters such a<br/>, including the battery’s energy storage capacity and instantaneous power output.<br/>7 battery open-circuit voltage<br/>8 battery internal resistance  </p>\n<p><strong>The battery sensor in the J367 battery monitoring control unit:</strong></p>\n<p>Knowing whether the battery has enough electrical energy to restart the engine is essential for the start-stop system to function properly.<br/>The control module is located directly on the “negative” terminal of the ground wire and is connected to the diagnostic interface via the LIN data bus.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/charge-batterie-c76863ff.webp\"/></figure>\n<p><strong>Signal Usage:</strong><br/>The battery sensor records the following values:<br/>– Battery temperature<br/>– Battery voltage<br/>– Charging current<br/>The battery temperature is calculated using a lookup table and the ambient temperature.<br/>It also allows for estimates of the battery’s charging time.<br/>Using the data obtained in this way, it is possible to adjust the charging control—particularly the charging voltage—to the battery’s state of charge and operating conditions. The goal is to increase the availability of the start-stop system by optimally utilizing data from the starter battery. </p>\n<p><strong>Consequences in the Event of a Malfunction</strong><br/>If the battery sensor is defective, the battery status can no longer be detected correctly.<br/>A fault is logged in the diagnostic interface’s fault memory. The start-stop system is deactivated. </p>\n<p><strong>Battery</strong></p>\n<p>The vehicle’s battery is housed in the engine compartment and protected by a battery tray. The size and type of battery depend on the engine version, equipment, and country-specific variant. Standard batteries, EFB batteries, and AGM batteries are used.<br/>Vehicles with gasoline engines and start/stop systems are equipped with an EFB battery, while vehicles with diesel engines and start/stop systems are equipped with an AGM battery. Vehicles with auxiliary heaters typically have an AGM battery.   </p>\n<p><strong>EFB</strong></p>\n<p>An EFB battery (short for Enhanced Flooded Battery) is a reinforced flooded battery. The positive plate inside the battery is coated with an additional layer of polyester mesh. This provides the battery’s active material with additional support on the plate. These batteries have greater resistance to charge-discharge cycles than standard batteries. During charging, an EFB battery is treated like a standard battery.    </p>\n<p><strong>AGM Battery</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-agm-f4b81a74.webp\"/></figure>\n<p>In AGM (Absorbent Glass Mat) batteries, the battery electrolyte is retained within a microporous glass mat. An AGM battery is characterized not only by even greater resistance to charge-discharge cycles compared to an EFB battery, but also by its leak-proof design. When charging, follow the charger’s user manual and, if applicable, select the AGM battery program.  </p>\n<p>In the case of AGM batteries, the automotive battery electrolyte is retained within a microporous glass mat. In addition to<br/>increased resistance to charge-discharge cycles, an AGM battery is characterized by its high level of leak resistance. Sealing is of crucial<br/>importance, particularly when the battery is installed in<br/>the passenger compartment. When charging, follow the charger’s user manual and, if necessary, select the program for<br/>AGM batteries.   </p>\n<p>Below, we can see the brand, serial number, and manufacturer of the battery</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-124711ff.webp\"/></figure>","transporter-t6-1-set-acc-control-in-1-km-h-increments":"<p><strong>Purpose</strong>: to adjust the ACC distance setting from the factory setting so that it can be set in 1 km/h increments by pressing the switch.  </p>\n<p>By default, the PLUS and MINUS buttons on the adaptive cruise control system adjust your speed in 10 km/h increments. You can change the coding in 1 km/h increments by briefly pressing the button. And use the old 10 km/h speed increments by pressing and holding the buttons.</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><br/> 3 – Click on ” <strong>Select</strong> ” and then click on “Select”. <strong><strong>13 – Regul Dist.</strong></strong> ” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>14117 <em>or</em></strong> <strong>20103</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>6</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>7</strong> – Select Byte <strong>02</strong></p>\n<p>Select bit <strong>6</strong> “Operation Mode 2”.</p>\n<p>Some speed controller modules may use a different coding or even have this parameter as an adaptation instead of the coding. Make sure that the option you are about to modify is correctly labeled.</p>\n<p>Module 13 → Adaptation → Mode de fonctionnement / Operation Mode → Mode de fonctionnement 2 / Operation Mode 2</p>","transporter-t6-1-speed-of-radar-deactivation-or-reversing-camera":"<p><strong>Purpose:</strong> Selects the speed at which the radar and/or reversing camera are deactivated.  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Switch-off speed for parking assist</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose a value between<strong>“0</strong>” and<strong>“15</strong>” km/h, depending on your preference.</p>","transporter-t6-1-start-stop-deactivation":"<p><strong>Purpose:</strong> to disable Start and Stop completely.  <br/></p>\n<p><em><strong>Watch out! There are 1 or 2 lines of coding to do here, depending on the method.</strong> <em>(After 2019 deactivation no longer works according to gateway reference “AA”)  </em></em><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><br/><strong>Method 1 (voltage method, recommended):</strong></p>\n<p><strong>VCDS :  </strong><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“Limite de tension de départ marche/arrêt” / “Start/Stop voltage limit”</strong>.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“12</strong>” (default value = <strong>7.6V</strong>) then validate.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_start_stop_change_voltage_limit_value-a50bc29b.webp\"/></figure>\n<p><strong><strong>OBDeleven:</strong></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenstartstoptension-ec0170bc.webp\"/></figure>\n<p><strong>YouTube video:</strong></p>\n<figure>\n</figure>\n<hr/>\n<p><strong>Method 2 (Temperature method):</strong></p>\n<p><strong>VCDS :</strong> </p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – On this page, at the top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start/Stopp Auntemperaturvorgabe-Minimaltemperatur</strong>”.</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“50</strong>” (default value = <strong>-50.0</strong>) and confirm.</p>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start/Stopp Auntemperaturvorgabe-Maximaltemperatur</strong>”.</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“50</strong>” (default value = <strong>-50.0</strong>) and confirm.</p>\n<p><strong><strong>OBDeleven:</strong></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenstarstoptemp-494422ad.webp\"/></figure>"};
